/**
 * The standard sample rates (Hz) the desk recognises, the pro-audio superset. One source of truth for the clock controller's `clock.allowed-rates` seed, the force row's validation ceiling and the device-rate probe fallback. What the operator is OFFERED is always the DEVICE's own `supportedRates`; this is the ceiling a write is refused by, never a menu.
 * @see data/rates.json
 */
export const STANDARD_SAMPLE_RATES = [
  44100,
  48000,
  88200,
  96000,
  176400,
  192000
];

/**
 * The quanta (buffer sizes, in frames, a count with no unit of its own) the console offers: the set a measurement grid or a probe takes its quanta from, beside the rates STANDARD_SAMPLE_RATES lists. A consumer that measures at fewer quanta takes a subset of this list and states it; it never keeps a list of its own. What the operator is OFFERED is still the engine's own choice, this is the ceiling a request is refused by.
 * @see data/rates.json
 */
export const STANDARD_QUANTA = [
  32,
  64,
  128,
  256,
  512,
  1024
];

